(function(){'use strict';if(typeof window.zohoPaymentsConfig==='undefined')return;var c=window.zohoPaymentsConfig;function setBusy(b,busy){if(busy){b.classList.add('is-loading');b.setAttribute('aria-busy','true');b.setAttribute('data-original-html',b.innerHTML);b.style.width=b.offsetWidth+'px';b.innerHTML='<span class="zoho-pay-spinner" aria-hidden="true"></span>';if(b.tagName.toLowerCase()==='button')b.disabled=!0}else{b.classList.remove('is-loading');b.removeAttribute('aria-busy');var orig=b.getAttribute('data-original-html');if(orig){b.innerHTML=orig;b.removeAttribute('data-original-html')}b.style.width='';if(b.tagName.toLowerCase()==='button')b.disabled=!1}}document.addEventListener('click',function(e){var btn=e.target.closest('.zoho-pay-button');if(!btn)return;e.preventDefault();if(btn.classList.contains('is-loading'))return;if(typeof window.ZPayments==='undefined'){alert(c.i18n.loading_sdk||'Zoho Payments SDK is loading. Please wait a moment...');return}if(!c.accountId||!c.checkoutApiKey){alert(c.i18n.not_configured||'Zoho Payments is not configured. Please configure Account ID and Checkout API Key in Admin Settings.');return}var amt=btn.getAttribute('data-amount')||'100',cur=btn.getAttribute('data-currency')||'INR',desc=btn.getAttribute('data-description')||'',red=btn.getAttribute('data-redirect')||'',sig=btn.getAttribute('data-sig')||'';setBusy(btn,!0);function fail(msg){setBusy(btn,!1);alert(msg||c.i18n.network_error)}function openWidget(session){var z;try{z=new window.ZPayments({account_id:c.accountId,domain:c.domain||'IN',otherOptions:{api_key:c.checkoutApiKey,is_test_mode:Boolean(c.isTestMode)}})}catch(err){console.error('Zoho Payments SDK init error:',err);fail('Could not initialize Zoho Payments widget: '+(err.message||err));return}var method=(typeof z.requestPaymentMethod==='function')?z.requestPaymentMethod:((typeof z.openCheckout==='function')?z.openCheckout:((typeof z.requestPayment==='function')?z.requestPayment:null));if(!method){console.error('Available methods on ZPayments:',z);fail('Zoho Payments checkout method is not available on this widget version.');return}var opts={amount:String(session.amount),currency_code:session.currency||'INR',payments_session_id:session.payments_session_id,description:session.description||''};function handleSuccess(resp){setBusy(btn,!1);if(typeof z.close==='function'){try{z.close()}catch(x){}}if(resp){var st=(resp.status||resp.payment_status||'').toLowerCase();if(st==='success'||st==='completed'||st==='paid'||Boolean(resp.payment_id)){if(red&&red.trim()!==''){window.location.href=red.trim()}}}}try{var ret=method.call(z,opts,function(cbResp){handleSuccess(cbResp)});if(ret&&typeof ret.then==='function'){ret.then(function(resp){handleSuccess(resp)}).catch(function(err){setBusy(btn,!1);if(typeof z.close==='function'){try{z.close()}catch(x){}}if(err&&(err.code==='widget_closed'||err.code==='checkout_closed'||err.message==='closed')){return}var m=(err&&(err.message||err.description||err.error))?(err.message||err.description||err.error):'Payment was cancelled or failed.';fail(m)})}}catch(callErr){console.error('Checkout launch error:',callErr);fail('Could not launch Zoho checkout: '+(callErr.message||callErr))}}function tryAjax(){if(!c.ajaxUrl){fail(c.i18n.network_error);return}var p=new URLSearchParams();p.append('action','zoho_payments_create_session');p.append('amount',amt);p.append('currency',cur);p.append('description',desc);p.append('redirect_url',red);p.append('sig',sig);fetch(c.ajaxUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},body:p.toString()}).then(function(r){return r.text()}).then(function(t){var d;try{d=JSON.parse(t)}catch(x){d=null}if(d&&d.success&&d.data&&d.data.payments_session_id){openWidget(d.data)}else if(d&&d.data&&d.data.message){fail(d.data.message)}else if(d&&d.message){fail(d.message)}else{fail(c.i18n.network_error)}}).catch(function(err){console.error('Ajax fail:',err);fail(c.i18n.network_error)})}if(!c.restUrl){tryAjax();return}fetch(c.restUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:amt,currency:cur,description:desc,redirect_url:red,sig:sig})}).then(function(r){return r.text().then(function(t){var d;try{d=JSON.parse(t)}catch(x){d=null}if(r.ok&&d&&d.success&&d.payments_session_id){openWidget(d)}else if(d&&d.message){fail(d.message)}else{tryAjax()}})}).catch(function(err){console.warn('REST error, fallback to Ajax:',err);tryAjax()})})})();